#!/usr/bin/env python3
"""Write the website's release report from actual local verification records."""
import hashlib, html, json
from pathlib import Path
R=Path(__file__).resolve().parent.parent
read=lambda p:json.loads((R/p).read_text())
s=read('verification/structure_checks.json');b=read('verification/browser_checks.json');v=read('verification/visual_checks.json');r=read('verification/reproducibility.json');m=read('source/build_summary.json')
assert not any(x['failed'] for x in (s,b,v,r))
E=html.escape
rows=[('Graph data',f'{m["graph_nodes"]:,} nodes · {m["graph_edges"]:,} keyed relationships · {m["graph_relation_types"]} relationship types','All original payload fields retained; no new source claims.'),('Static records','193 W · 50 O · 123 P · 33 F · 111 B','510 source records, each present in HTML and complete-node JSON.'),('Practice layer','84 descriptors · 87 historical occurrences','Kept separate from empirical evidence.'),('Group pages','9 streams · 30 topics · 5 earlier volumes · 13 chapters','Actual chapter citations and editorial mappings labelled separately.'),('Default atlas','193 sources · 0 context nodes · 64 edges','Exact default source and edge IDs checked.'),('Structural validation',f'{s["passed"]} passed · {s["failed"]} failed',f'{s["internal_links_checked"]:,} local link/asset/fragment references checked across {s["html_pages_checked"]} active HTML pages.'),('Browser validation',f'{b["passed"]} passed · {b["failed"]} failed','Includes an exact keyed-edge comparison for each of all 297 relationship switches.'),('Responsive / photo checks',f'{v["passed"]} passed · {v["failed"]} failed','Desktop, tablet and mobile-sized Chromium viewports; real portrait loads on scroll.'),('Reproducible build',f'{r["passed"]} of {r["outputs_tested"]} generated outputs identical','Two consecutive local builds matched by SHA-256, including the catalogue ZIP.')]
trs=''.join('<tr><th>'+E(a)+'</th><td>'+E(c)+'</td><td>'+E(d)+'</td></tr>' for a,c,d in rows)
links=[('structure_checks.json','Static path and record checks'),('browser_checks.json','Browser checks and navigation boundary'),('relationship_switch_checks.json','All 297 edge-type switch results'),('visual_checks.json','Responsive and portrait checks'),('reproducibility.json','Byte-for-byte regeneration checks'),('TEST_METHOD.md','Detailed test method'),('../source/author_provenance.json','Photo and biography provenance'),('../source/original_catalogue_provenance.json','Inherited catalogue provenance'),('../source/page_inventory.json','Generated page inventory'),('../SHA256SUMS.txt','Release file manifest')]
ls=''.join('<li><a href="'+E(p)+'">'+E(t)+'</a></li>' for p,t in links)
imgs=''.join('<figure><a href="'+p+'"><img src="'+p+'" alt="'+E(t)+'" loading="lazy" style="max-width:100%;height:auto;border:1px solid #dce3e9;border-radius:12px"></a><figcaption>'+E(t)+'</figcaption></figure>' for p,t in [('home_desktop.png','Desktop landing page with catalogues and author biography'),('home_tablet.png','Tablet-sized landing page'),('atlas_mobile.png','Mobile-sized v12 atlas with the original Polimi-only preset'),('catalogue_mobile.png','Mobile-sized Fowler catalogue search')])
body=f'''<p class="eyebrow">Website release v12.1 · 14 October 2026</p><h1>Release verification</h1><p class="intro">A complete static website around the frozen v12 Knowledge Atlas. This is a presentation and packaging release, not a new research audit.</p><div class="actions"><a class="button primary" href="../index.html">Project homepage</a><a class="button" href="../catalogues/index.html">Catalogues</a><a class="button" href="../swe_knowledge_graph.html">Atlas</a></div><section class="section"><h2>What is included</h2><p>The package includes a landing page, the existing interactive atlas, static catalogue pages for the five source collections, one page for each stream/topic/earlier volume/book chapter, practice and occurrence catalogues, an author page and portrait, JSON/CSV data, the original graph exports, the inherited catalogue files, a README and deployment instructions. Catalogue content is present in HTML without JavaScript.</p><div style="overflow-x:auto"><table><thead><tr><th>Area</th><th>Result</th><th>Scope</th></tr></thead><tbody>{trs}</tbody></table></div></section><section class="section"><h2>What the checks do not establish</h2><div class="caution"><strong>Browser-test boundary.</strong> Administrator policy blocked local HTTP navigation. Tests therefore used Chromium with packaged CSS, JavaScript and images inlined into Playwright’s set_content. The production query handler was exercised with explicit parameters; local file and anchor targets were checked separately. This is not a successful GitHub deployment or native Safari/iPad test.</div><p>External source URLs were inventoried rather than checked afresh. Original restricted-access qualifications, source-audit boundaries and editorial mappings remain unchanged. No empirical replication, field-pilot result or institutional endorsement is implied.</p></section><section class="section"><h2>Attribution and author photo</h2><p>The starting bibliography is credited prominently to Alfonso Fuggetta, Damian Andrew Tamburri and Alessandro Margara, Software Engineering @ PoliMi. Each added collection retains its actual authorship; the Fowler collection acknowledges Birgitta Böckeler’s editorial contribution.</p><p>The author portrait was extracted from Enrico Papalini’s own Non-Deterministic Loop Engineering author page (PDF page 277 / printed page 265), composited with its alpha mask on white and resized to 631 × 640 pixels. No generative modification was applied. The short biography is adapted from that page and does not assert an independently rechecked current job title.</p><p><a href="../attribution.html">Full credits and evidence boundaries</a></p></section><section class="section"><h2>Verification records</h2><ul>{ls}</ul></section><section class="section"><h2>Rendered checks</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:24px">{imgs}</div></section>'''
text='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="author" content="Enrico Papalini"><meta name="description" content="Verification scope for the static Knowledge Atlas and catalogue website."><title>Release verification · Knowledge Atlas v12.1</title><link rel="stylesheet" href="../assets/site.css"><style>table{width:100%;border-collapse:collapse;font-size:.93rem}th,td{padding:14px 12px;text-align:left;vertical-align:top;border-bottom:1px solid #dce3e9}th{min-width:150px}figcaption{font-size:.8rem;color:#617181;margin-top:9px}</style></head><body><a class="skip" href="#main">Skip to content</a><header class="site-head"><div class="nav"><a class="brand" href="../index.html"><span><small>AI & Software Engineering</small><strong>Knowledge Atlas</strong></span></a><nav class="nav-links" aria-label="Main navigation"><a href="../swe_knowledge_graph.html">Atlas</a><a href="../catalogues/index.html">Catalogues</a><a href="../about.html">About</a><a href="../downloads.html">Downloads</a></nav></div></header><main id="main" class="wrap">'''+body+'''</main><footer class="site-foot"><div class="foot-inner"><p>Independent atlas by Enrico Papalini · Graph snapshot 13 October 2026</p><p><a href="../README.md">README</a> · <a href="../attribution.html">Attribution</a></p></div></footer></body></html>'''
(R/'verification/report.html').write_text(text,encoding='utf-8');print('Wrote release report from verified records.')
